<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function kimpu_register_homepage_hero_controls( $c ) {
    $section = 'kimpu_homepage_hero';
    kimpu_homepage_setting( $c, 'kimpu_hero_title', __( 'Build a better digital presence.', 'kimpu-multipurpose' ), 'sanitize_text_field' ); kimpu_homepage_control( $c, 'kimpu_hero_title', __( 'Heading', 'kimpu-multipurpose' ), $section );
    kimpu_homepage_setting( $c, 'kimpu_hero_text', __( 'A clean, flexible WordPress foundation designed to grow with your ideas.', 'kimpu-multipurpose' ), 'sanitize_textarea_field' ); kimpu_homepage_control( $c, 'kimpu_hero_text', __( 'Description', 'kimpu-multipurpose' ), $section, 'textarea' );
    $text = array( 'kimpu_hero_eyebrow' => array( __( 'WELCOME TO YOUR NEXT CHAPTER', 'kimpu-multipurpose' ), __( 'Eyebrow Text', 'kimpu-multipurpose' ), 'text', 'sanitize_text_field' ), 'kimpu_hero_primary_text' => array( __( 'Explore articles', 'kimpu-multipurpose' ), __( 'Primary Button Text', 'kimpu-multipurpose' ), 'text', 'sanitize_text_field' ), 'kimpu_hero_primary_url' => array( '#latest', __( 'Primary Button URL', 'kimpu-multipurpose' ), 'url', 'esc_url_raw' ), 'kimpu_hero_secondary_text' => array( __( 'Learn more', 'kimpu-multipurpose' ), __( 'Secondary Button Text', 'kimpu-multipurpose' ), 'text', 'sanitize_text_field' ), 'kimpu_hero_secondary_url' => array( '#about-theme', __( 'Secondary Button URL', 'kimpu-multipurpose' ), 'url', 'esc_url_raw' ), 'kimpu_hero_image_alt' => array( '', __( 'Hero Image Alt Text', 'kimpu-multipurpose' ), 'text', 'sanitize_text_field' ), 'kimpu_hero_content_alignment' => array( 'left', __( 'Content Alignment', 'kimpu-multipurpose' ), 'select', array( 'left' => __( 'Left', 'kimpu-multipurpose' ), 'center' => __( 'Center', 'kimpu-multipurpose' ), 'right' => __( 'Right', 'kimpu-multipurpose' ) ) ) );
    foreach ( $text as $id => $data ) { $sanitize = 'select' === $data[2] ? function( $v ) use ( $data ) { return array_key_exists( $v, $data[3] ) ? $v : array_key_first( $data[3] ); } : $data[3]; kimpu_homepage_setting( $c, $id, $data[0], $sanitize ); kimpu_homepage_control( $c, $id, $data[1], $section, $data[2], 'select' === $data[2] ? $data[3] : array() ); }
